SELECT s.PLAN_SITE_ID, s.PLAN_ID, s.REF_ID FROM `PLAN_SITE` s
  LEFT JOIN `PLAN_CANDIDATE_SITE` c ON c.PLAN_ID = s.PLAN_ID AND c.CANDIDATE_CODE = s.REF_ID
 WHERE s.REF_KIND = 'candidate' AND c.PLAN_CANDIDATE_SITE_ID IS NULL;
