-- M1
ALTER TABLE `PLAN_SITE` ADD COLUMN `PLAN_CANDIDATE_SITE_ID` BIGINT UNSIGNED NULL COMMENT 'Candidate plot this row points at (REF_KIND = candidate)' AFTER `REF_ID`;
UPDATE `PLAN_SITE` s JOIN `PLAN_CANDIDATE_SITE` c ON c.`PLAN_ID` = s.`PLAN_ID` AND c.`CANDIDATE_CODE` = s.`REF_ID` SET s.`PLAN_CANDIDATE_SITE_ID` = c.`PLAN_CANDIDATE_SITE_ID` WHERE s.`REF_KIND` = 'candidate';
ALTER TABLE `PLAN_SITE` ADD KEY `IDX_PLAN_SITE_PLAN_CANDIDATE_SITE_ID` (`PLAN_CANDIDATE_SITE_ID`),
  ADD CONSTRAINT `FK_PLAN_SITE_PLAN_CANDIDATE_SITE_ID` FOREIGN KEY (`PLAN_CANDIDATE_SITE_ID`) REFERENCES `PLAN_CANDIDATE_SITE` (`PLAN_CANDIDATE_SITE_ID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  ADD CONSTRAINT `CK_PLAN_SITE_CANDIDATE` CHECK ((`REF_KIND` = 'candidate') = (`PLAN_CANDIDATE_SITE_ID` IS NOT NULL));
